"""Strict checkpoints generated by this codebase. No key translation layer."""

from pathlib import Path
import torch

FORMAT = "sbs.v2"


def save_checkpoint(path, model, config, epoch, step, optimizer=None, **extra):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    network = model.module if hasattr(model, "module") else model
    payload = {
        "format": FORMAT,
        "config": config,
        "model_state": network.state_dict(),
        "epoch": int(epoch),
        "step": int(step),
        **extra,
    }
    if optimizer is not None:
        payload["optimizer_state"] = optimizer.state_dict()
    temporary = path.with_name(path.name + ".tmp")
    torch.save(payload, temporary)
    temporary.replace(path)


def load_checkpoint(path, model, optimizer=None, expected_config=None):
    payload = torch.load(Path(path), map_location="cpu", weights_only=True)
    if not isinstance(payload, dict) or payload.get("format") != FORMAT:
        raise ValueError("Expected a checkpoint generated by this SBS codebase (sbs.v2)")
    state = payload.get("model_state")
    if not isinstance(state, dict) or not state:
        raise ValueError("Checkpoint has no model tensors")
    if any(not isinstance(t, torch.Tensor) or (t.is_floating_point() and not torch.isfinite(t).all())
           for t in state.values()):
        raise ValueError("Checkpoint contains invalid or nonfinite model tensors")
    if expected_config is not None:
        for key in ("dataset", "model", "ignore_index"):
            if payload.get("config", {}).get(key) != expected_config.get(key):
                raise ValueError(f"Checkpoint/config mismatch: {key}")
    if optimizer is not None and "optimizer_state" not in payload:
        raise ValueError("Pretrained checkpoint has no optimizer state; use it for evaluation, not --resume")
    network = model.module if hasattr(model, "module") else model
    network.load_state_dict(payload["model_state"], strict=True)
    if optimizer is not None:
        if "optimizer_state" not in payload:
            raise ValueError("Checkpoint does not contain optimizer state")
        optimizer.load_state_dict(payload["optimizer_state"])
    return payload
